// ✅ render nothing (or a placeholder) until mounted on the client
function SafeClock() {
  const [now, setNow] = useState<string | null>(null);
  useEffect(() => setNow(new Date().toLocaleTimeString()), []);
  return <span suppressHydrationWarning>{now ?? '--:--'}</span>;
}

