// app/actions.ts
'use server';
import { revalidateTag } from 'next/cache';
import { z } from 'zod';
import { getSession } from '@/lib/auth';

const schema = z.object({ title: z.string().min(1).max(200) });

export async function createPost(formData: FormData) {
  const session = await getSession();
  if (!session) throw new Error('Unauthorized'); // authorize INSIDE the action
  const { title } = schema.parse({ title: formData.get('title') });
  await db.post.create({ data: { title, authorId: session.userId } });
  revalidateTag('posts'); // fresh data in the same round trip
}

